"""Auto-generated tearsheet: turns computed tables into a readable summary."""
from __future__ import annotations

from pathlib import Path

import pandas as pd


def write_tearsheet(
    study: str,
    sample_label: str,
    factor_stats: pd.DataFrame,
    grs: pd.DataFrame,
    reg_tables: dict[str, pd.DataFrame],
    out_path: str | Path,
    notes: str = "",
) -> Path:
    """Write a Markdown tearsheet summarizing the study's headline results."""
    out_path = Path(out_path)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    L: list[str] = [f"# {study} — Tearsheet", "", f"Sample: {sample_label}", ""]

    L += ["## Factor premia (annualized)", "",
          "| Factor | Mean | Vol | t(mean) | Sharpe |",
          "|---|---:|---:|---:|---:|"]
    for f, r in factor_stats.iterrows():
        L.append(f"| {f} | {r['ann_mean_pct']:.2f}% | {r['ann_vol_pct']:.2f}% "
                 f"| {r['t_mean']:.2f} | {r['sharpe']:.2f} |")
    L += [""]

    L += ["## Model comparison", "",
          "| Model | GRS F | p-value | Significant alphas (|t|>2) | Mean adj. R² |",
          "|---|---:|---:|---:|---:|"]
    for model, grow in grs.iterrows():
        reg = reg_tables[model]
        n_sig = int((reg["t_alpha"].abs() > 2).sum())
        L.append(f"| {model} | {grow['GRS_F']:.3f} | {grow['p_value']:.2e} "
                 f"| {n_sig}/{len(reg)} | {reg['adj_R2'].mean():.3f} |")
    L += [""]

    for model, reg in reg_tables.items():
        worst = reg["alpha_ann_pct"].idxmin()
        L += [f"## {model}: largest (most negative) alpha",
              f"- **{worst}**: {reg.loc[worst, 'alpha_ann_pct']:.2f}%/yr "
              f"(t = {reg.loc[worst, 't_alpha']:.2f})", ""]

    L += ["## Interpretation",
          "- A GRS p-value below conventional levels rejects the joint "
          "hypothesis that all alphas are zero: the model does not fully "
          "price the test assets.",
          "- Compare models by the number of significant alphas and mean "
          "adjusted R², not by any single portfolio.",
          "",
          "_Generated by factorlab. Educational project — not investment advice._"]
    if notes:
        L += ["", notes]
    out_path.write_text("\n".join(L) + "\n")
    return out_path
